<template><div class="page-heading"><div><h1>个人中心</h1><p>管理你的身份信息、密码和登录设备。</p></div></div><div class="form-card"><div class="profile-hero"><el-avatar :size="72" :src="app.user?.avatar_url || ''">{{ (app.user?.display_name || '管')[0] }}</el-avatar><div><h3>{{ app.user?.display_name }}</h3><p>@{{ app.user?.username }} · 本地工作台管理员</p></div></div><el-divider/><el-form :model="profile" label-width="90px"><el-form-item label="显示名称"><el-input v-model="profile.display_name"/></el-form-item><el-form-item label="头像地址"><el-input v-model="profile.avatar_url" placeholder="粘贴图片 URL，或留空使用默认头像"/></el-form-item><el-button type="primary" @click="saveProfile">保存个人资料</el-button></el-form><el-divider/><h3>修改登录密码</h3><el-form :model="password" label-width="90px" style="max-width:480px"><el-form-item label="原密码"><el-input v-model="password.old_password" type="password" show-password/></el-form-item><el-form-item label="新密码"><el-input v-model="password.new_password" type="password" show-password/></el-form-item><div class="page-actions"><el-button @click="changePassword">修改密码</el-button><el-button plain @click="resetPassword">重置密码</el-button></div></el-form><el-divider/><div class="danger-zone"><div><b>强制下线所有设备</b><p>使所有已登录的 Token 立即失效，适合发现异常登录时使用。</p></div><el-button type="danger" plain @click="logoutAll">立即下线</el-button></div></div></template>
<script setup>import{reactive}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{useRouter}from'vue-router';import{api}from'../api/http';import{useAppStore}from'../stores';const app=useAppStore(),router=useRouter(),profile=reactive({display_name:app.user?.display_name||'',avatar_url:app.user?.avatar_url||''}),password=reactive({old_password:'',new_password:''});async function saveProfile(){const res=await api.profile(profile);app.user=res.data;localStorage.setItem('workbench_user',JSON.stringify(res.data));ElMessage.success('个人资料已保存')}async function changePassword(){if(!password.old_password||!password.new_password)return ElMessage.warning('请完整填写密码');await api.changePassword(password);ElMessage.success('密码已修改，请重新登录');app.clearSession();router.push('/login')}async function resetPassword(){if(!password.new_password)return ElMessage.warning('请输入新密码');await ElMessageBox.confirm('重置后当前登录会失效，确认继续？','安全确认',{type:'warning'});await api.resetPassword({new_password:password.new_password});app.clearSession();router.push('/login')}async function logoutAll(){await ElMessageBox.confirm('所有设备都会退出登录，确认继续？','安全确认',{type:'warning'});await app.logoutAll();router.push('/login')}</script>
